const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Punjab and Haryana region (approximate bounding box)
  const punjabHaryana = ee.Geometry.Polygon([
    [[73.5, 28.5], [77.5, 28.5], [77.5, 32.0], [73.5, 32.0], [73.5, 28.5]]
  ]);

  // VIIRS active fire collection
  const firms = ee.ImageCollection('FIRMS');

  // Function to count fires for a given November
  function countNovemberFires(year) {
    const startDate = ee.Date.fromYMD(year, 11, 1);
    const endDate = ee.Date.fromYMD(year, 11, 30);

    const col = firms
      .filterDate(startDate, endDate)
      .filterBounds(punjabHaryana);

    const count = col.size().getInfo();

    if (count === 0) {
      return { year: year, count: 0, hasData: false };
    }

    // Sum all fire pixels across all images in November
    const fireSum = col.select(['T21'])
      .sum()
      .reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: punjabHaryana,
        scale: 1000,
        maxPixels: 1e9
      })
      .get('T21');

    const fireCount = fireSum.getInfo();

    return { year: year, count: fireCount || 0, hasData: count > 0 };
  }

  console.log('Counting November fires for Punjab and Haryana...\n');

  // Count fires for 2012-2023
  const historicalYears = [];
  for (let year = 2012; year <= 2023; year++) {
    const result = countNovemberFires(year);
    historicalYears.push(result);
    console.log(`Nov ${year}: ${result.count} fire detections (Images: ${result.hasData ? 'Yes' : 'No'})`);
  }

  // Count fires for November 2024
  const nov2024 = countNovemberFires(2024);
  console.log(`Nov 2024: ${nov2024.count} fire detections (Images: ${nov2024.hasData ? 'Yes' : 'No'})\n`);

  // Check for missing data
  const missingData = historicalYears.some(y => !y.hasData) || !nov2024.hasData;
  if (missingData) {
    console.log('Missing data for one or more years.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Find minimum in historical period
  const historicalCounts = historicalYears.map(y => y.count);
  const minHistorical = Math.min(...historicalCounts);
  const maxHistorical = Math.max(...historicalCounts);

  console.log(`Historical range (2012-2023): ${minHistorical} to ${maxHistorical}`);
  console.log(`November 2024 count: ${nov2024.count}`);

  // Compare
  if (nov2024.count < minHistorical) {
    console.log('\nNovember 2024 had fewer fires than any November from 2012-2023.');
    console.log('<answer>A</answer>');
  } else {
    console.log('\nNovember 2024 did NOT have fewer fires than all previous Novembers.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
